use super::*;

/// Rewrite a record's `code` so its DERIVABLE imports sit in ONE canonical block at the top — the exact
/// slot the emitter re-renders them into — and hand back the derived specs alongside. This is the
/// `bsc graph imports normalize` core (imports-are-derived-from-the-composes-graph, option A: normalize
/// FIRST, then migrate).
///
/// FLOOR imports (`@/…` resolving to no record `provides`) and any statement tree-sitter could not
/// structure are LEFT WHERE THEY ARE, in the body — they stay hand-written. Because the canonical block
/// is rendered by the SAME [`bsc_record::imports_fmt::body_with_imports`] the materializer uses, a later
/// `migrate` that strips this block re-emits byte-for-byte: parity by CONSTRUCTION. Idempotent —
/// normalizing already-normalized code returns it unchanged.
pub fn normalize_code(code: &str, provides: &HashSet<String>) -> NormalizedImports {
    let mut derived: Vec<ImportSpec> = Vec::new();
    let mut cut: Vec<(usize, usize)> = Vec::new();
    for (start, end, specs) in import_spans(code) {
        // Every spec in one statement shares its `from`, so the whole statement is derived or floor.
        let floor = specs
            .first()
            .is_some_and(|s| s.from.starts_with("@/") && !provides.contains(&s.from));
        if specs.is_empty() || floor {
            continue;
        }
        derived.extend(specs);
        // Swallow the statement's trailing newline so excising it leaves no blank line behind.
        let mut e = end;
        if code[e..].starts_with("\r\n") {
            e += 2;
        } else if code[e..].starts_with('\n') {
            e += 1;
        }
        cut.push((start, e));
    }
    if cut.is_empty() {
        return NormalizedImports { code: code.to_string(), derived };
    }
    let mut cleaned = code.to_string();
    for (s, e) in cut.into_iter().rev() {
        cleaned.replace_range(s..e, "");
    }
    // Excising a statement leaves the blank line that separated the import block from the body; drop
    // those leading blanks so [`layout`] re-adds EXACTLY one — otherwise re-normalizing piles them up.
    let (head, body) = bsc_record::imports_fmt::split_head(&cleaned);
    let body = body.trim_start_matches(['\n', '\r']);
    let fmt: Vec<_> = derived.iter().map(to_fmt).collect();
    let code = bsc_record::imports_fmt::layout(head, &bsc_record::imports_fmt::render_import_block(&fmt), body);
    NormalizedImports { code, derived }
}
